--- funnel.py ---
import sqlite3, json
from collections import defaultdict
c = sqlite3.connect('analytics.db')
steps = ['install','tutorial_complete','first_match','purchase']
ph = ','.join('?'*len(steps))
plat = dict(c.execute("select user_id,platform from users where is_test=0"))
first = defaultdict(dict)
for uid, name, ts in c.execute(f"select user_id,name,ts from events where name in ({ph})", steps):
    if uid in plat and (name not in first[uid] or ts < first[uid][name]):
        first[uid][name] = ts
funnel = {p: {s:0 for s in steps} for p in set(plat.values())}
for uid, f in first.items():
    prev = None
    p = plat[uid]
    for s in steps:
        if s in f and (prev is None or f[s] >= prev):
            funnel[p][s] += 1
            prev = f[s]
        else:
            break
biggest = {}
for p, counts in funnel.items():
    convs = [(counts[steps[i]]/counts[steps[i-1]] if counts[steps[i-1]] else 1, steps[i]) for i in range(1,len(steps))]
    biggest[p] = min(convs)[1]
result = {'funnel': funnel, 'biggest_drop': biggest}
json.dump(result, open('result.json','w'), indent=2)
print(json.dumps(result, indent=2))
print(dict(c.execute("select platform,count(*) from users where is_test=0 group by platform")))


